export const newManualAccount=():ManualAccount=>({version:3,cashBalance:10_000,startingBalance:10_000,realisedPnl:0,fees:0,fundingPnl:0,fundingPayments:[],positions:{},fills:[],idempotencyKeys:[],settings:{...DEFAULT_MANUAL_SETTINGS},marginSnapshot:buildPaperMarginAccountSnapshot(10_000,[],0),updatedAt:new Date(0).toISOString()});
const number=(value:unknown)=>{const parsed=typeof value==="number"?value:Number(value);return Number.isFinite(parsed)?parsed:null};
export function manualEquity(account:ManualAccount,marks:Record<string,number>={}){return account.cashBalance+Object.values(account.positions).reduce((total,position)=>{const mark=marks[position.symbol];return total+(Number.isFinite(mark)?(mark-position.entryPrice)*position.quantity*(position.side==="long"?1:-1):0)},0)}
export function usedManualMargin(account:ManualAccount){return Object.values(account.positions).reduce((sum,p)=>sum+(p.margin??p.quantity*p.entryPrice/p.leverage),0)}
export function calculateManualSizing(input:{sizeMode:ManualSizeMode;amount:unknown;leverage:unknown;side?:ManualSide;stopLoss?:unknown;minLeverage?:unknown;maxLeverage?:unknown},equity:number,price:number){
 const minLeverage=number(input.minLeverage)??1,maxLeverage=number(input.maxLeverage)??20,leverageValue=number(input.leverage);if(minLeverage<1||maxLeverage<minLeverage)fail("INVALID_LEVERAGE","leverage","Invalid contract leverage range.");if(leverageValue===null||leverageValue<minLeverage||leverageValue>maxLeverage)fail("INVALID_LEVERAGE","leverage",`Leverage must be between ${minLeverage}× and ${maxLeverage}× for this contract.`);
 const amountValue=number(input.amount);if(amountValue===null||amountValue<=0)fail("INVALID_AMOUNT","amount",input.sizeMode==="equity-percent"?"Percentage must be between 0.01% and 100%.":"Enter an amount greater than zero.");
 const leverage=leverageValue as number,amount=amountValue as number;
 if(input.sizeMode==="equity-percent"&&(amount<.01||amount>100))fail("INVALID_PERCENTAGE","amount","Percentage must be between 0.01% and 100%.");
 if(!Number.isFinite(price)||price<=0)fail("PRICE_UNAVAILABLE","marketPrice","Current public market price is unavailable.");
 try{const result=sizePaperPosition({mode:input.sizeMode,amount,leverage,equity,price,side:input.side??"long",stopLoss:number(input.stopLoss),minLeverage,maxLeverage});if(!result.riskAmount)return {margin:result.margin,notional:result.notional,quantity:result.quantity,leverage:result.leverage};return result}catch(error){const code=error instanceof Error?error.message:"INVALID_SIZING";return fail(code,code==="INVALID_RISK_STOP"?"stopLoss":"amount",code==="INVALID_RISK_STOP"?"Risk percentage sizing requires a valid protective stop.":code==="INSUFFICIENT_EQUITY"?"Required margin exceeds paper equity.":"Invalid position sizing values.")}
}
