export async function readManualAccount(userId:string){try{const raw=JSON.parse(await readFile(path(userId),"utf8")) as Partial<ManualAccount>&{version?:number;settings?:Partial<ManualSettings>};const base=newManualAccount(),positions=Object.fromEntries(Object.entries(raw.positions??{}).map(([symbol,p])=>{const old=p as Partial<ManualPosition>;const margin=old.margin??Number(old.quantity)*Number(old.entryPrice)/Math.max(1,Number(old.leverage));return [symbol,{...old,tradeId:old.tradeId??`legacy-${String(old.openedAt??"").replace(/\W/g,"")}-${symbol}`,marketKey:old.marketKey??`mexc:futures:${symbol}`,marketType:"futures",symbol,margin,marginMode:old.marginMode??"isolated",entryFee:old.entryFee??0,riskPriceSource:old.riskPriceSource??"last",lastRiskPrice:old.lastRiskPrice??old.entryPrice,estimatedLiquidation:old.estimatedLiquidation??estimateLiquidation({side:old.side!,entryPrice:old.entryPrice!,quantity:old.quantity!,marginMode:"isolated",assignedMargin:margin,crossCollateral:Number(raw.cashBalance??base.cashBalance),entryFee:0})}] }));return refreshAccountRisk({...base,...raw,positions,fundingPnl:raw.fundingPnl??0,fundingPayments:Array.isArray(raw.fundingPayments)?raw.fundingPayments:[],version:3,settings:{...DEFAULT_MANUAL_SETTINGS,...raw.settings}} as ManualAccount)}catch{return newManualAccount()}}
async function writeManualAccount(userId:string,value:ManualAccount){await mkdir(join(root(),"manual-paper"),{recursive:true});const target=path(userId),temp=`${target}.${process.pid}.${Date.now()}.tmp`;await writeFile(temp,JSON.stringify(value,null,2)+"\n",{mode:0o600});await rename(temp,target)}
const queues=new Map<string,Promise<unknown>>();async function serial<T>(userId:string,fn:()=>Promise<T>):Promise<T>{const previous=queues.get(userId)??Promise.resolve();let release!:()=>void;const gate=new Promise<void>(r=>release=r);queues.set(userId,previous.then(()=>gate));await previous;try{return await fn()}finally{release()}}
export async function latestPublicRiskPrice(symbol:string,previous?:number){if(!/^[A-Z0-9]{1,20}_[A-Z0-9]{1,20}$/.test(symbol))fail("INVALID_SYMBOL","symbol","Invalid market symbol.");const response=await fetch(`https://contract.mexc.com/api/v1/contract/ticker?symbol=${encodeURIComponent(symbol)}`,{signal:AbortSignal.timeout(5000),cache:"no-store"});if(!response.ok)fail("PRICE_UNAVAILABLE","marketPrice","Current public risk price is unavailable.");const body=await response.json() as {data?:{fairPrice?:unknown;lastPrice?:unknown}};const selected=selectRiskPrice(body.data?.fairPrice,body.data?.lastPrice,previous);if(!selected)return fail("PRICE_UNAVAILABLE","marketPrice","Fair and Last prices are unavailable.");return selected}
export async function latestPublicPrice(symbol:string){return (await latestPublicRiskPrice(symbol)).price}
const contractMetadataCache=new Map<string,{at:number;value:MexcContractMetadata}>();
export async function latestPublicContractMetadata(symbol:string){if(!/^[A-Z0-9]{1,20}_[A-Z0-9]{1,20}$/.test(symbol))fail("INVALID_SYMBOL","symbol","Invalid market symbol.");const cached=contractMetadataCache.get(symbol),now=Date.now();if(cached&&now-cached.at<300_000)return cached.value;const response=await fetch(`https://api.mexc.com/api/v1/contract/detail?symbol=${encodeURIComponent(symbol)}`,{signal:AbortSignal.timeout(5000),cache:"no-store"});if(!response.ok)fail("CONTRACT_METADATA_UNAVAILABLE","symbol","Current public MEXC contract rules are unavailable.");try{const value=parseMexcContractMetadata(await response.json(),symbol);contractMetadataCache.set(symbol,{at:now,value});return value}catch{return fail("CONTRACT_METADATA_UNAVAILABLE","symbol","Current public MEXC contract rules are unavailable.")}}
const fundingRateCache=new Map<string,{at:number;value:MexcFundingRateSnapshot}>();
