export async function latestPublicFundingHistory(symbol:string){if(!/^[A-Z0-9]{1,20}_[A-Z0-9]{1,20}$/.test(symbol))fail("INVALID_SYMBOL","symbol","Invalid market symbol.");const cached=fundingHistoryCache.get(symbol),now=Date.now();if(cached&&now-cached.at<30_000)return cached.value;const response=await fetch(`https://contract.mexc.com/api/v1/contract/funding_rate/history?symbol=${encodeURIComponent(symbol)}&page_num=1&page_size=1000`,{signal:AbortSignal.timeout(5000),cache:"no-store"});if(!response.ok)fail("FUNDING_HISTORY_UNAVAILABLE","funding","Public MEXC funding history is unavailable.");try{const value=parseMexcFundingHistory(await response.json(),symbol);fundingHistoryCache.set(symbol,{at:now,value});return value}catch{return fail("FUNDING_HISTORY_UNAVAILABLE","funding","Public MEXC funding history is unavailable.")}}
function fundingPositionSnapshot(funding?:MexcFundingRateSnapshot){return funding?{fundingRate:funding.fundingRate,fundingMinRate:funding.minFundingRate,fundingMaxRate:funding.maxFundingRate,fundingCollectCycleHours:funding.collectCycleHours,nextFundingTime:funding.nextSettleTime,fundingSource:funding.source,fundingObservedAt:funding.observedAt}:{} as const}
function applyFundingHistory(account:ManualAccount,userId:string,position:ManualPosition,riskPrice:number,priceSource:RiskPriceSource,current?:MexcFundingRateSnapshot,history:readonly MexcFundingSettlement[]=[]){const observedAt=Date.now(),due=dueMexcFundingSettlements(history,Date.parse(position.openedAt),position.lastFundingSettlementAt,observedAt);for(const settlement of due){const paymentId=`${position.tradeId}:${settlement.settleTime}`;if(account.fundingPayments.some(payment=>payment.paymentId===paymentId))continue;const calculated=calculatePaperFundingPayment({side:position.side,quantity:position.quantity,observedPrice:riskPrice,fundingRate:settlement.fundingRate}),before=account.cashBalance,after=Math.max(0,before+calculated.calculatedCashDelta),cashDelta=after-before;account.cashBalance=after;account.fundingPnl+=cashDelta;account.realisedPnl+=cashDelta;position.fundingPnl=(position.fundingPnl??0)+cashDelta;position.lastFundingSettlementAt=settlement.settleTime;account.fundingPayments.push({paymentId,tradeId:position.tradeId,userId,symbol:position.symbol,side:position.side,settleTime:settlement.settleTime,observedAt,price:riskPrice,priceSource,quantity:position.quantity,notional:calculated.notional,fundingRate:settlement.fundingRate,calculatedCashDelta:calculated.calculatedCashDelta,cashDelta,balanceCapped:Math.abs(cashDelta-calculated.calculatedCashDelta)>1e-12,source:settlement.source,calculationMethod:"observed-risk-price-notional",resultingBalance:account.cashBalance})}if(current?.symbol===position.symbol)Object.assign(position,fundingPositionSnapshot(current));account.fundingPayments=account.fundingPayments.slice(-1000)}
function validatedContractOrder(notional:number,price:number,contract:MexcContractMetadata){try{return sizeMexcContractOrder(notional,price,contract)}catch(error){const code=error instanceof Error?error.message:"INVALID_CONTRACT_NOTIONAL";if(code==="CONTRACT_VOLUME_BELOW_MINIMUM")return fail(code,"amount",`Order must contain at least ${contract.minVol} contracts.`);if(code==="CONTRACT_VOLUME_ABOVE_MAXIMUM")return fail(code,"amount",`Order cannot exceed ${contract.maxVol} contracts.`);return fail("INVALID_CONTRACT_NOTIONAL","amount","The requested size cannot be represented by this contract.")}}
function validateExits(side:ManualSide,entry:number,stop:unknown,target:unknown,priceUnit?:number){const stopLoss=stop==null?null:number(stop),takeProfit=target==null?null:number(target);if(stopLoss!==null&&priceUnit&&!isMexcStepAligned(stopLoss,priceUnit))fail("INVALID_PRICE_STEP","stopLoss",`Stop loss must use ${priceUnit} price increments.`);if(takeProfit!==null&&priceUnit&&!isMexcStepAligned(takeProfit,priceUnit))fail("INVALID_PRICE_STEP","takeProfit",`Take profit must use ${priceUnit} price increments.`);if(stopLoss!==null&&((side==="long"&&stopLoss>=entry)||(side==="short"&&stopLoss<=entry)))fail("INVALID_STOP_LOSS","stopLoss",side==="long"?"Stop loss must be below entry for a long.":"Stop loss must be above entry for a short.");if(takeProfit!==null&&((side==="long"&&takeProfit<=entry)||(side==="short"&&takeProfit>=entry)))fail("INVALID_TAKE_PROFIT","takeProfit",side==="long"?"Take profit must be above entry for a long.":"Take profit must be below entry for a short.");return {stopLoss,takeProfit}}
