function positionRiskExposure(position:ManualPosition,tier:PaperRiskTierSnapshot){return tier.riskLimitType==="BY_VOLUME"?(position.contractVolume??(position.contractSize?position.quantity/position.contractSize:position.quantity)):position.quantity*position.entryPrice}
function legacyPositionRiskTier(position:ManualPosition,settings:ManualSettings){return legacyPaperRiskTierSnapshot({symbol:position.symbol,riskLimitType:position.contractVolume!==undefined?"BY_VOLUME":"UNKNOWN",exposure:position.contractVolume??position.quantity*position.entryPrice,maintenanceMarginRate:settings.maintenanceMarginPct/100,initialMarginRate:1/Math.max(1,position.leverage),maxLeverage:Math.max(1,position.leverage),capturedAt:Number.isFinite(Date.parse(position.openedAt))?Date.parse(position.openedAt):Date.now()})}
