function marginModelInput(position:ManualPosition,tier:PaperRiskTierSnapshot,settings:ManualSettings):PaperMarginPositionInput{return {symbol:position.symbol,side:position.side,quantity:position.quantity,entryPrice:position.entryPrice,markPrice:Number.isFinite(position.lastRiskPrice)&&position.lastRiskPrice>0?position.lastRiskPrice:position.entryPrice,margin:position.margin,marginMode:position.marginMode,maintenanceMarginRate:tier.maintenanceMarginRate,liquidationPenaltyRate:settings.liquidationPenaltyPct/100}}
function refreshAccountRisk(account:ManualAccount){const tiered=Object.fromEntries(Object.entries(account.positions).map(([symbol,position])=>{const current=positionRiskTier(position,account.settings);try{return [symbol,{...position,riskTier:reselectPaperRiskTier(current,positionRiskExposure(position,current))}]}catch{return [symbol,{...position,riskTier:current}]}}));account.positions=tiered;const inputs=Object.values(account.positions).map(position=>marginModelInput(position,positionRiskTier(position,account.settings),account.settings)),snapshot=buildPaperMarginAccountSnapshot(account.cashBalance,inputs);account.marginSnapshot=snapshot;for(const [symbol,position] of Object.entries(account.positions)){const tier=positionRiskTier(position,account.settings),marginInput=marginModelInput(position,tier,account.settings),marginAudit=buildPaperPositionMarginAudit(marginInput,snapshot),crossCollateral=Math.max(1e-9,marginAudit.collateralAvailableToPosition);try{const liquidationAudit=auditPaperLiquidation({side:position.side,entryPrice:position.entryPrice,quantity:position.quantity,marginMode:position.marginMode,assignedMargin:position.margin,crossCollateral,entryFee:position.marginMode==="isolated"?position.entryFee:0,maintenanceMarginRate:tier.maintenanceMarginRate,liquidationPenaltyRate:account.settings.liquidationPenaltyPct/100});account.positions[symbol]={...position,riskTier:tier,marginAudit,estimatedLiquidation:liquidationAudit.estimatedLiquidation,bankruptcyPrice:liquidationAudit.bankruptcyPrice,liquidationAudit}}catch{account.positions[symbol]={...position,riskTier:tier,marginAudit}}}return account}
