function validatedEntryRiskTier(contract:MexcContractMetadata,contractVolume:number,notional:number,leverage:number){try{const tier=selectMexcContractRiskTier(contract,{contractVolume,notional});if(leverage-tier.maxLeverage>1e-10)return fail("RISK_TIER_LEVERAGE_EXCEEDED","leverage",`Tier ${tier.level} allows at most ${tier.maxLeverage}× leverage for this position size.`);return tier}catch(error){if(error instanceof ManualPaperError)throw error;const code=error instanceof Error?error.message:"INVALID_RISK_TIER";if(code==="RISK_LIMIT_EXCEEDED")return fail(code,"amount","Requested position exceeds the documented public MEXC risk schedule.");return fail("RISK_TIER_UNAVAILABLE","amount","The requested position cannot be mapped to a valid maintenance tier.")}}
