export async function attachManualHistoricalDizyFlow(userId:string,tradeId:string,reference:HistoricalDizyFlowReference){return serial(userId,async()=>{const account=await readManualAccount(userId),index=account.fills.findIndex(fill=>fill.side==="close"&&fill.tradeId===tradeId&&fill.openedAt&&fill.closeReason);if(index<0)return null;const existing=account.fills[index].historicalDizyFlow;if(existing?.memoryId&&existing.memoryId!==reference.memoryId)throw new ManualPaperError("FLOW_REFERENCE_CONFLICT","tradeId","Completed Paper trade already references different flow evidence.");account.fills[index]={...account.fills[index],historicalDizyFlow:reference};account.updatedAt=new Date().toISOString();await writeManualAccount(userId,account);return account.fills[index]})}
export async function completedManualTrade(userId:string,tradeId:string){return (await readManualAccount(userId)).fills.find(fill=>fill.side==="close"&&fill.tradeId===tradeId&&Boolean(fill.openedAt)&&Boolean(fill.closeReason))??null}
async function flattenManualPositionsLegacy(userId:string,key:string,prices:Record<string,number>){return serial(userId,async()=>{const account=await readManualAccount(userId);if(!account.settings.enabled)fail("MANUAL_PAPER_DISABLED","settings.enabled","Manual Paper is disabled.");validateKey(account,key);const symbols=Object.keys(account.positions);for(const symbol of symbols)if(!Number.isFinite(prices[symbol])||prices[symbol]<=0)fail("PRICE_UNAVAILABLE","marketPrice","Public price unavailable for "+symbol+".");for(const symbol of symbols){const position=account.positions[symbol];if(position)closeAt(account,userId,symbol,prices[symbol],key+":"+symbol,"manual",manualReduceOnlyPlan(position,position.quantity,position.quantity,"flatten-all"))}account.idempotencyKeys.push(key);account.updatedAt=new Date().toISOString();await writeManualAccount(userId,account);return account})}

export async function flattenManualPositions(userId:string,key:string,markets:Record<string,number|{price:number;depth:DepthEnvelope;contract:MexcContractMetadata}>){if(Object.values(markets).every(value=>typeof value==="number"))return flattenManualPositionsLegacy(userId,key,markets as Record<string,number>);return serial(userId,async()=>{const account=await readManualAccount(userId);if(!account.settings.enabled)fail("MANUAL_PAPER_DISABLED","settings.enabled","Manual Paper is disabled.");validateKey(account,key);const symbols=Object.keys(account.positions);for(const symbol of symbols){const market=markets[symbol],price=typeof market==="number"?market:market?.price;if(!Number.isFinite(price)||Number(price)<=0)fail("PRICE_UNAVAILABLE","marketPrice","Public price unavailable for "+symbol+".")}for(const symbol of symbols){const market=markets[symbol],position=account.positions[symbol];if(!position)continue;const reduceOnlyPlan=manualReduceOnlyPlan(position,position.quantity,position.quantity,"flatten-all");if(typeof market==="number")closeAt(account,userId,symbol,market,key+":"+symbol,"manual",reduceOnlyPlan);else try{closeWithDepthAt(account,userId,symbol,market.price,key+":"+symbol,position.quantity,market.depth,market.contract,"manual",reduceOnlyPlan)}catch(error){if(error instanceof ManualPaperError&&error.code==="DEPTH_LIQUIDITY_BELOW_MINIMUM")continue;throw error}}account.idempotencyKeys.push(key);account.fills=account.fills.slice(-500);account.idempotencyKeys=account.idempotencyKeys.slice(-1000);account.updatedAt=new Date().toISOString();await writeManualAccount(userId,account);return account})}


export async function updateManualSettings(userId:string,input:Partial<ManualSettings>){return serial(userId,async()=>{const account=await readManualAccount(userId);account.settings={...account.settings,...input};account.updatedAt=new Date().toISOString();await writeManualAccount(userId,account);return account})}
export async function resetManualAccount(userId:string,confirmation:string){if(confirmation!=="RESET MANUAL PAPER")fail("RESET_CONFIRMATION_REQUIRED","confirmation","Reset confirmation required.");return serial(userId,async()=>{const account=newManualAccount();account.updatedAt=new Date().toISOString();await writeManualAccount(userId,account);return account})}
